/**
 * struct usb_host_endpoint - host-side endpoint descriptor and queue
 * @desc: descriptor for this endpoint, wMaxPacketSize in native byteorder
 * @ss_ep_comp: SuperSpeed companion descriptor for this endpoint
 * @ssp_isoc_ep_comp: SuperSpeedPlus isoc companion descriptor for this endpoint
 * @eusb2_isoc_ep_comp: eUSB2 isoc companion descriptor for this endpoint
 * @urb_list: urbs queued to this endpoint; maintained by usbcore
 * @hcpriv: for use by HCD; typically holds hardware dma queue head (QH)
 *	with one or more transfer descriptors (TDs) per urb; must be preserved
 *	by core while BW is allocated for the endpoint
 * @ep_dev: ep_device for sysfs info
 * @extra: descriptors following this endpoint in the configuration
 * @extralen: how many bytes of "extra" are valid
 * @enabled: URBs may be submitted to this endpoint
 * @streams: number of USB-3 streams allocated on the endpoint
 *
 * USB requests are always queued to a given endpoint, identified by a
 * descriptor within an active interface in a given USB configuration.
 */
struct usb_host_endpoint {
	struct usb_endpoint_descriptor			desc;
	struct usb_ss_ep_comp_descriptor		ss_ep_comp;
	struct usb_ssp_isoc_ep_comp_descriptor		ssp_isoc_ep_comp;
	struct usb_eusb2_isoc_ep_comp_descriptor	eusb2_isoc_ep_comp;
	struct list_head		urb_list;
	void				*hcpriv;
	struct ep_device		*ep_dev;	/* For sysfs info */

	unsigned char *extra;   /* Extra descriptors */
	int extralen;
	int enabled;
	int streams;
};

/* host-side wrapper for one interface setting's parsed descriptors */
struct usb_host_interface {
	struct usb_interface_descriptor	desc;

	int extralen;
	unsigned char *extra;   /* Extra descriptors */

	/* array of desc.bNumEndpoints endpoints associated with this
	 * interface setting.  these will be in no particular order.
	 */
	struct usb_host_endpoint *endpoint;

	char *string;		/* iInterface string, if present */
};

/* USB_DT_DEVICE: Device descriptor */
struct usb_device_descriptor {
	__u8  bLength;
	__u8  bDescriptorType;

	__le16 bcdUSB;
	__u8  bDeviceClass;
	__u8  bDeviceSubClass;
	__u8  bDeviceProtocol;
	__u8  bMaxPacketSize0;
	__le16 idVendor;
	__le16 idProduct;
	__le16 bcdDevice;
	__u8  iManufacturer;
	__u8  iProduct;
	__u8  iSerialNumber;
	__u8  bNumConfigurations;
} __attribute__ ((packed));

#define USB_DT_DEVICE_SIZE		18

/* USB_DT_CONFIG: Configuration descriptor information.
 *
 * USB_DT_OTHER_SPEED_CONFIG is the same descriptor, except that the
 * descriptor type is different.  Highspeed-capable devices can look
 * different depending on what speed they're currently running.  Only
 * devices with a USB_DT_DEVICE_QUALIFIER have any OTHER_SPEED_CONFIG
 * descriptors.
 */
struct usb_config_descriptor {
	__u8  bLength;
	__u8  bDescriptorType;

	__le16 wTotalLength;
	__u8  bNumInterfaces;
	__u8  bConfigurationValue;
	__u8  iConfiguration;
	__u8  bmAttributes;
	__u8  bMaxPower;
} __attribute__ ((packed));

#define USB_DT_CONFIG_SIZE		9

/* USB_DT_INTERFACE: Interface descriptor */
struct usb_interface_descriptor {
	__u8  bLength;
	__u8  bDescriptorType;

	__u8  bInterfaceNumber;
	__u8  bAlternateSetting;
	__u8  bNumEndpoints;
	__u8  bInterfaceClass;
	__u8  bInterfaceSubClass;
	__u8  bInterfaceProtocol;
	__u8  iInterface;
} __attribute__ ((packed));

#define USB_DT_INTERFACE_SIZE		9

/*-------------------------------------------------------------------------*/

/* USB_DT_ENDPOINT: Endpoint descriptor */
struct usb_endpoint_descriptor {
	__u8  bLength;
	__u8  bDescriptorType;

	__u8  bEndpointAddress;
	__u8  bmAttributes;
	__le16 wMaxPacketSize;
	__u8  bInterval;

	/* NOTE:  these two are _only_ in audio endpoints. */
	/* use USB_DT_ENDPOINT*_SIZE in bLength, not sizeof. */
	__u8  bRefresh;
	__u8  bSynchAddress;
} __attribute__ ((packed));

#define USB_DT_ENDPOINT_SIZE		7
#define USB_DT_ENDPOINT_AUDIO_SIZE	9	/* Audio extension */


/*
 * Endpoints
 */
#define USB_ENDPOINT_NUMBER_MASK	0x0f	/* in bEndpointAddress */
#define USB_ENDPOINT_DIR_MASK		0x80

#define USB_ENDPOINT_XFERTYPE_MASK	0x03	/* in bmAttributes */
#define USB_ENDPOINT_XFER_CONTROL	0
#define USB_ENDPOINT_XFER_ISOC		1
#define USB_ENDPOINT_XFER_BULK		2
#define USB_ENDPOINT_XFER_INT		3
#define USB_ENDPOINT_MAX_ADJUSTABLE	0x80

#define USB_ENDPOINT_MAXP_MASK	0x07ff
#define USB_EP_MAXP_MULT_SHIFT	11
#define USB_EP_MAXP_MULT_MASK	(3 << USB_EP_MAXP_MULT_SHIFT)

/**
 * usb_endpoint_maxp - get endpoint's max packet size
 * @epd: endpoint to be checked
 *
 * Returns @epd's max packet bits [10:0]
 */
static inline int usb_endpoint_maxp(const struct usb_endpoint_descriptor *epd)
{
	return __le16_to_cpu(epd->wMaxPacketSize) & USB_ENDPOINT_MAXP_MASK;
}

#include "usb.h"


#define USB_MAXALTSETTING		128	/* Hard limit */

#define USB_MAXCONFIG			8	/* Arbitrary limit */

d = (struct usb_endpoint_descriptor *) buffer;
bcdUSB = le16_to_cpu(udev->descriptor.bcdUSB);
buffer += d->bLength;
size -= d->bLength;

if (d->bLength >= USB_DT_ENDPOINT_AUDIO_SIZE)
	n = USB_DT_ENDPOINT_AUDIO_SIZE;
else if (d->bLength >= USB_DT_ENDPOINT_SIZE)
	n = USB_DT_ENDPOINT_SIZE;
else {
	dev_notice(ddev, "config %d interface %d altsetting %d has an "
	    "invalid endpoint descriptor of length %d, skipping\n",
	    cfgno, inum, asnum, d->bLength);
	goto skip_to_next_endpoint_or_interface_descriptor;
}

i = usb_endpoint_num(d);
if (i == 0) {
	dev_notice(ddev, "config %d interface %d altsetting %d has an "
	    "invalid descriptor for endpoint zero, skipping\n",
	    cfgno, inum, asnum);
	goto skip_to_next_endpoint_or_interface_descriptor;
}

/* Only store as many endpoints as we have room for */
if (ifp->desc.bNumEndpoints >= num_ep)
	goto skip_to_next_endpoint_or_interface_descriptor;

/* Save a copy of the descriptor and use it instead of the original */
endpoint = &ifp->endpoint[ifp->desc.bNumEndpoints];
memcpy(&endpoint->desc, d, n);
d = &endpoint->desc;

/* Clear the reserved bits in bEndpointAddress */
i = d->bEndpointAddress &
		(USB_ENDPOINT_DIR_MASK | USB_ENDPOINT_NUMBER_MASK);
if (i != d->bEndpointAddress) {
	dev_notice(ddev, "config %d interface %d altsetting %d has an endpoint descriptor with address 0x%X, changing to 0x%X\n",
	    cfgno, inum, asnum, d->bEndpointAddress, i);
	endpoint->desc.bEndpointAddress = i;
}

/* Check for duplicate endpoint addresses */
if (config_endpoint_is_duplicate(config, inum, asnum, d)) {
	dev_notice(ddev, "config %d interface %d altsetting %d has a duplicate endpoint with address 0x%X, skipping\n",
			cfgno, inum, asnum, d->bEndpointAddress);
	goto skip_to_next_endpoint_or_interface_descriptor;
}

/* Ignore some endpoints */
if (udev->quirks & USB_QUIRK_ENDPOINT_IGNORE) {
	if (usb_endpoint_is_ignored(udev, ifp, d)) {
		dev_notice(ddev, "config %d interface %d altsetting %d has an ignored endpoint with address 0x%X, skipping\n",
				cfgno, inum, asnum,
				d->bEndpointAddress);
		goto skip_to_next_endpoint_or_interface_descriptor;
	}
}

/* Accept this endpoint */
++ifp->desc.bNumEndpoints;

 * Validate the wMaxPacketSize field.
 * eUSB2 devices (see USB 2.0 Double Isochronous IN ECN 9.6.6 Endpoint)
 * and devices with isochronous endpoints in altsetting 0 (see USB 2.0
 * end of section 5.6.3) have wMaxPacketSize = 0.
 * So don't warn about those.
 */
maxp = le16_to_cpu(endpoint->desc.wMaxPacketSize);

if (maxp == 0 && bcdUSB != 0x0220 &&
    !(usb_endpoint_xfer_isoc(d) && asnum == 0))
	dev_notice(ddev, "config %d interface %d altsetting %d endpoint 0x%X has invalid wMaxPacketSize 0\n",
	    cfgno, inum, asnum, d->bEndpointAddress);

/* Find the highest legal maxpacket size for this endpoint */
i = 0;		/* additional transactions per microframe */
switch (udev->speed) {
case USB_SPEED_LOW:
	maxpacket_maxes = low_speed_maxpacket_maxes;
	break;
case USB_SPEED_FULL:
	maxpacket_maxes = full_speed_maxpacket_maxes;
	break;
case USB_SPEED_HIGH:
	/* Multiple-transactions bits are allowed only for HS periodic endpoints */
	if (usb_endpoint_xfer_int(d) || usb_endpoint_xfer_isoc(d)) {
		i = maxp & USB_EP_MAXP_MULT_MASK;
		maxp &= ~i;
	}
	fallthrough;
default:
	maxpacket_maxes = high_speed_maxpacket_maxes;
	break;
case USB_SPEED_SUPER:
case USB_SPEED_SUPER_PLUS:
	maxpacket_maxes = super_speed_maxpacket_maxes;
	break;
}
j = maxpacket_maxes[usb_endpoint_type(&endpoint->desc)];

if (maxp > j) {
	dev_notice(ddev, "config %d interface %d altsetting %d endpoint 0x%X has invalid maxpacket %d, setting to %d\n",
	    cfgno, inum, asnum, d->bEndpointAddress, maxp, j);
	maxp = j;
	endpoint->desc.wMaxPacketSize = cpu_to_le16(i | maxp);
}

/*
 * Some buggy high speed devices have bulk endpoints using
 * maxpacket sizes other than 512.  High speed HCDs may not
 * be able to handle that particular bug, so let's warn...
 */

if (d->bLength < USB_DT_INTERFACE_SIZE)
	goto skip_to_next_interface_descriptor;

/* Which interface entry is this? */
intfc = NULL;
inum = d->bInterfaceNumber;
for (i = 0; i < config->desc.bNumInterfaces; ++i) {
	if (inums[i] == inum) {
		intfc = config->intf_cache[i];
		break;
	}
}
if (!intfc || intfc->num_altsetting >= nalts[i])
	goto skip_to_next_interface_descriptor;

/* Check for duplicate altsetting entries */
asnum = d->bAlternateSetting;
for ((i = 0, alt = &intfc->altsetting[0]);
      i < intfc->num_altsetting;
     (++i, ++alt)) {
	if (alt->desc.bAlternateSetting == asnum) {
		dev_notice(ddev, "Duplicate descriptor for config %d "
		    "interface %d altsetting %d, skipping\n",
		    cfgno, inum, asnum);
		goto skip_to_next_interface_descriptor;
	}
}

++intfc->num_altsetting;
memcpy(&alt->desc, d, USB_DT_INTERFACE_SIZE);

/* Allocate space for the right(?) number of endpoints */
num_ep = num_ep_orig = alt->desc.bNumEndpoints;
alt->desc.bNumEndpoints = 0;		/* Use as a counter */
if (num_ep > USB_MAXENDPOINTS) {
	dev_notice(ddev, "too many endpoints for config %d interface %d "
	    "altsetting %d: %d, using maximum allowed: %d\n",
	    cfgno, inum, asnum, num_ep, USB_MAXENDPOINTS);
	num_ep = USB_MAXENDPOINTS;
}

if (num_ep > 0) {
	/* Can't allocate 0 bytes */
	len = sizeof(struct usb_host_endpoint) * num_ep;
	alt->endpoint = kzalloc(len, GFP_KERNEL);
	if (!alt->endpoint)
		return -ENOMEM;
}

/* Parse all the endpoint descriptors */
n = 0;
while (size > 0) {
	if (((struct usb_descriptor_header *) buffer)->bDescriptorType

memcpy(&config->desc, buffer, USB_DT_CONFIG_SIZE);
nintf = nintf_orig = config->desc.bNumInterfaces;
config->desc.bNumInterfaces = 0;	// Adjusted later

if (config->desc.bDescriptorType != USB_DT_CONFIG ||
    config->desc.bLength < USB_DT_CONFIG_SIZE ||
    config->desc.bLength > size) {
	dev_notice(ddev, "invalid descriptor for config index %d: "
	    "type = 0x%X, length = %d\n", cfgidx,
	    config->desc.bDescriptorType, config->desc.bLength);
	return -EINVAL;
}
cfgno = config->desc.bConfigurationValue;

buffer += config->desc.bLength;
size -= config->desc.bLength;

if (nintf > USB_MAXINTERFACES) {
	dev_notice(ddev, "config %d has too many interfaces: %d, "
	    "using maximum allowed: %d\n",
	    cfgno, nintf, USB_MAXINTERFACES);
	nintf = USB_MAXINTERFACES;
}

/* Have we already encountered this interface?
 * Count its altsettings */
for (i = 0; i < n; ++i) {
	if (inums[i] == inum)
		break;
}
if (i < n) {
	if (nalts[i] < 255)
		++nalts[i];
} else if (n < USB_MAXINTERFACES) {
	inums[n] = inum;
	nalts[n] = 1;
	++n;
}

size = buffer2 - buffer;
config->desc.wTotalLength = cpu_to_le16(buffer2 - buffer0);

if (n != nintf)
	dev_notice(ddev, "config %d has %d interface%s, different from "
	    "the descriptor's value: %d\n",
	    cfgno, n, str_plural(n), nintf_orig);
else if (n == 0)
	dev_notice(ddev, "config %d has no interfaces?\n", cfgno);
config->desc.bNumInterfaces = nintf = n;

/* Check for missing interface numbers */
for (i = 0; i < nintf; ++i) {
	for (j = 0; j < nintf; ++j) {
		if (inums[j] == i)
			break;
	}
	if (j >= nintf)
		dev_notice(ddev, "config %d has no interface number "
		    "%d\n", cfgno, i);
}

/* Allocate the usb_interface_caches and altsetting arrays */
for (i = 0; i < nintf; ++i) {
	j = nalts[i];
	if (j > USB_MAXALTSETTING) {
		dev_notice(ddev, "too many alternate settings for "
		    "config %d interface %d: %d, "
		    "using maximum allowed: %d\n",
		    cfgno, inums[i], j, USB_MAXALTSETTING);
		nalts[i] = j = USB_MAXALTSETTING;
	}

	intfc = kzalloc(struct_size(intfc, altsetting, j), GFP_KERNEL);
	config->intf_cache[i] = intfc;
	if (!intfc)
		return -ENOMEM;
	kref_init(&intfc->ref);
}

int ncfg = dev->descriptor.bNumConfigurations;
unsigned int cfgno, length;
unsigned char *bigbuffer;
struct usb_config_descriptor *desc;
int result;
size_t usb_config_req_size;

/*
 * We usually start by grabbing the first 9-bytes descriptor so we know
 * how long the whole configuration is. Some devices with quirky
 * firmware will fail enumeration, so if the quirk is set, use 255 instead,
 * mirroring the behavior of Windows.
 */
if (dev->quirks & USB_QUIRK_WINDOWS_CONFIG_REQ_SIZE)
	usb_config_req_size = 255;
else
	usb_config_req_size = USB_DT_CONFIG_SIZE;

if (ncfg > USB_MAXCONFIG) {
	dev_notice(ddev, "too many configurations: %d, "
	    "using maximum allowed: %d\n", ncfg, USB_MAXCONFIG);
	dev->descriptor.bNumConfigurations = ncfg = USB_MAXCONFIG;
}

if (ncfg < 1 && dev->quirks & USB_QUIRK_FORCE_ONE_CONFIG) {
	dev_info(ddev, "Device claims zero configurations, forcing to 1\n");
	dev->descriptor.bNumConfigurations = 1;
	ncfg = 1;
} else if (ncfg < 1) {
	dev_err(ddev, "no configurations\n");
	return -EINVAL;
}

length = ncfg * sizeof(struct usb_host_config);
dev->config = kzalloc(length, GFP_KERNEL);
if (!dev->config)
	return -ENOMEM;

/*
 * Initialize the new interface structures and the
 * hc/hcd/usbcore interface/endpoint state.
 */
for (i = 0; i < nintf; ++i) {
	struct usb_interface_cache *intfc;
	struct usb_interface *intf;
	struct usb_host_interface *alt;
	u8 ifnum;

	cp->interface[i] = intf = new_interfaces[i];
	intfc = cp->intf_cache[i];
	intf->altsetting = intfc->altsetting;
	intf->num_altsetting = intfc->num_altsetting;
	intf->authorized = !!HCD_INTF_AUTHORIZED(hcd);
	kref_get(&intfc->ref);

	alt = usb_altnum_to_altsetting(intf, 0);

	/* No altsetting 0?  We'll assume the first altsetting.
	 * We could use a GetInterface call, but if a device is
	 * so non-compliant that it doesn't have altsetting 0
	 * then I wouldn't trust its reply anyway.
	 */
	if (!alt)
		alt = &intf->altsetting[0];

	ifnum = alt->desc.bInterfaceNumber;
	intf->intf_assoc = find_iad(dev, cp, ifnum);
	intf->cur_altsetting = alt;
	usb_enable_interface(dev, intf, true);
	intf->dev.parent = &dev->dev;
	if (usb_of_has_combined_node(dev)) {
		device_set_of_node_from_dev(&intf->dev, &dev->dev);
	} else {
		intf->dev.of_node = usb_of_get_interface_node(dev,
				configuration, ifnum);
	}
	ACPI_COMPANION_SET(&intf->dev, ACPI_COMPANION(&dev->dev));
	intf->dev.driver = NULL;
	intf->dev.bus = &usb_bus_type;
	intf->dev.type = &usb_if_device_type;
	intf->dev.groups = usb_interface_groups;
	INIT_WORK(&intf->reset_ws, __usb_queue_reset_device);
	INIT_WORK(&intf->wireless_status_work, __usb_wireless_status_intf);
	intf->minor = -1;
	device_initialize(&intf->dev);
	pm_runtime_no_callbacks(&intf->dev);
	dev_set_name(&intf->dev, "%d-%s:%d.%d", dev->bus->busnum,
			dev->devpath, configuration, ifnum);
	usb_get_dev(dev);

static int usb_probe_interface(struct device *dev)
{
	struct usb_driver *driver = to_usb_driver(dev->driver);
	struct usb_interface *intf = to_usb_interface(dev);
	struct usb_device *udev = interface_to_usbdev(intf);
	const struct usb_device_id *id;
	struct usb_device_id id_copy;
	int error = -ENODEV;
	int lpm_disable_error = -ENODEV;

	dev_dbg(dev, "%s\n", __func__);

	intf->needs_binding = 0;

	if (usb_device_is_owned(udev))
		return error;

	if (udev->authorized == 0) {
		dev_info(&intf->dev, "Device is not authorized for usage\n");
		return error;
	} else if (intf->authorized == 0) {
		dev_info(&intf->dev, "Interface %d is not authorized for usage\n",
				intf->altsetting->desc.bInterfaceNumber);
		return error;
	}

	id = usb_match_dynamic_id(intf, driver, &id_copy);
	if (!id)
		id = usb_match_id(intf, driver->id_table);
	if (!id)
		return error;

/* Carry out a deferred switch to altsetting 0 */
if (intf->needs_altsetting0) {
	error = usb_set_interface(udev, intf->altsetting[0].
			desc.bInterfaceNumber, 0);
	if (error < 0)
		goto err;
	intf->needs_altsetting0 = 0;
}

error = driver->probe(intf, id);
if (error)
	goto err;

intf->condition = USB_INTERFACE_BOUND;

/* If the LPM disable succeeded, balance the ref counts. */
if (!lpm_disable_error)
	usb_unlocked_enable_lpm(udev);

usb_autosuspend_device(udev);
return error;

const struct bus_type usb_bus_type = {
	.name =		"usb",
	.match =	usb_device_match,
	.uevent =	usb_uevent,
	.need_parent_lock =	true,
};

/*
 * __device_driver_lock - acquire locks needed to manipulate dev->drv
 * @dev: Device we will update driver info for
 * @parent: Parent device. Needed if the bus requires parent lock
 *
 * This function will take the required locks for manipulating dev->drv.
 * Normally this will just be the @dev lock, but when called for a USB
 * interface, @parent lock will be held as well.
 */
static void __device_driver_lock(struct device *dev, struct device *parent)
{
	if (parent && dev->bus->need_parent_lock)
		device_lock(parent);
	device_lock(dev);
}

/*
 * __device_driver_unlock - release locks needed to manipulate dev->drv
 * @dev: Device we will update driver info for
 * @parent: Parent device. Needed if the bus requires parent lock
 *
 * This function will release the required locks for manipulating dev->drv.
 * Normally this will just be the @dev lock, but when called for a
 * USB interface, @parent lock will be released as well.
 */
static void __device_driver_unlock(struct device *dev, struct device *parent)
{
	device_unlock(dev);
	if (parent && dev->bus->need_parent_lock)
		device_unlock(parent);
}

#define usb_ep_attr(field, format_string)			\
static ssize_t field##_show(struct device *dev,			\
			       struct device_attribute *attr,	\
			       char *buf)			\
{								\
	struct ep_device *ep = to_ep_device(dev);		\
	return sysfs_emit(buf, format_string, ep->desc->field);	\
}								\
static DEVICE_ATTR_RO(field)

usb_ep_attr(bLength, "%02x\n");
usb_ep_attr(bEndpointAddress, "%02x\n");
usb_ep_attr(bmAttributes, "%02x\n");
usb_ep_attr(bInterval, "%02x\n");

static ssize_t wMaxPacketSize_show(struct device *dev,
				   struct device_attribute *attr, char *buf)
{
	struct ep_device *ep = to_ep_device(dev);
	return sysfs_emit(buf, "%04x\n", usb_endpoint_maxp(ep->desc));
}
static DEVICE_ATTR_RO(wMaxPacketSize);

int usb_create_ep_devs(struct device *parent,
			struct usb_host_endpoint *endpoint,
			struct usb_device *udev)
{
	struct ep_device *ep_dev;
	int retval;

	ep_dev = kzalloc(sizeof(*ep_dev), GFP_KERNEL);
	if (!ep_dev) {
		retval = -ENOMEM;
		goto exit;
	}

	ep_dev->desc = &endpoint->desc;
	ep_dev->udev = udev;
	ep_dev->dev.groups = ep_dev_groups;
	ep_dev->dev.type = &usb_ep_device_type;
	ep_dev->dev.parent = parent;
	dev_set_name(&ep_dev->dev, "ep_%02x", endpoint->desc.bEndpointAddress);

	retval = device_register(&ep_dev->dev);

static ssize_t speed_show(struct device *dev, struct device_attribute *attr,
			  char *buf)
{
	struct usb_device *udev;
	char *speed;

	udev = to_usb_device(dev);

	switch (udev->speed) {
	case USB_SPEED_LOW:
		speed = "1.5";
		break;
	case USB_SPEED_UNKNOWN:
	case USB_SPEED_FULL:
		speed = "12";
		break;
	case USB_SPEED_HIGH:
		speed = "480";
		break;
	case USB_SPEED_SUPER:
		speed = "5000";
		break;
	case USB_SPEED_SUPER_PLUS:
		if (udev->ssp_rate == USB_SSP_GEN_2x2)
			speed = "20000";
		else
			speed = "10000";
		break;
	default:
		speed = "unknown";
	}
	return sysfs_emit(buf, "%s\n", speed);
}
static DEVICE_ATTR_RO(speed);
